   340→        if (!ValidateWithBlockValidator(block, parent, out validationMessage))
   341→        {
   342→            return (TryCacheResult(ValidationResult.Invalid, validationMessage), validationMessage);
   343→        }
   344→
   345→        ValidationCompletion blockProcessed =
   346→            _blockValidationTasks.GetOrAdd(
   347→                block.Hash!,
   348→                static (k) => new(TaskCreationOptions.RunContinuationsAsynchronously));
   349→
   350→        try
   351→        {
   352→            CancellationTokenSource cts = new();
   353→            Task timeoutTask = Task.Delay(_timeout, cts.Token);
   354→
   355→            AddBlockResult addResult = await _blockTree
   356→                .SuggestBlockAsync(block, BlockTreeSuggestOptions.ForceDontSetAsMain)
   357→                .AsTask().TimeoutOn(timeoutTask);
   358→
   359→            result = addResult switch
   360→            {
   361→                AddBlockResult.InvalidBlock => ValidationResult.Invalid,
   362→                // if the block is marked as AlreadyKnown by the block tree then it means it has already
   363→                // been suggested. there are three possibilities, either the block hasn't been processed yet,
   364→                // the block was processed and returned invalid but this wasn't saved anywhere or the block was
   365→                // processed and marked as valid.
   366→                // if marked as processed by the blocktree then return VALID, otherwise null so that it's process a few lines below
   367→                AddBlockResult.AlreadyKnown => _blockTree.WasProcessed(block.Number, block.Hash!) ? ValidationResult.Valid : null,
   368→                _ => null
   369→            };
   370→
   371→            validationMessage = addResult switch
   372→            {
   373→                AddBlockResult.InvalidBlock => "Block couldn't be added to the tree.",
   374→                AddBlockResult.AlreadyKnown => "Block was already known in the tree.",
   375→                _ => null
   376→            };
   377→
   378→            if (!result.HasValue)
   379→            {
   380→                // we don't know the result of processing the block, either because
   381→                // it is the first time we add it to the tree or it's AlreadyKnown in
   382→                // the tree but hasn't yet been processed. if it's the second case
   383→                // probably the block is already in the processing queue as a result
   384→                // of a previous newPayload or the block being discovered during syncing
   385→                // but add it to the processing queue just in case.
   386→                await _processingQueue.Enqueue(block, processingOptions);
   387→                (result, validationMessage) = await blockProcessed.Task.TimeoutOn(timeoutTask, cts);
   388→            }
   389→        }
   390→        catch (TimeoutException)
   391→        {
   392→            // we timed out while processing the block, result will be null and we will return SYNCING below, no need to do anything
   393→            if (_logger.IsDebug) _logger.Debug($"Block {block.ToString(Block.Format.FullHashAndNumber)} timed out when processing. Assume Syncing.");
   394→        }
   395→
   396→        return (TryCacheResult(result ?? ValidationResult.Syncing, validationMessage), validationMessage);
   397→    }
   398→
   399→    private void GetProcessingQueueOnBlockRemoved(object? o, BlockRemovedEventArgs e)
   400→    {
   401→        if (!_blockValidationTasks.TryRemove(e.BlockHash, out ValidationCompletion? blockProcessed))
   402→        {
   403→            // If we don't have a task for this block, it means it was already processed or removed.
   404→            return;
   405→        }
   406→
   407→        if (e.ProcessingResult == ProcessingResult.Exception)
   408→        {
   409→            BlockchainException? exception = new(e.Exception?.Message ?? "Block processing threw exception.", e.Exception);
   410→            blockProcessed.TrySetException(exception);
   411→            return;
   412→        }
   413→
   414→        ValidationResult? validationResult = e.ProcessingResult switch
   415→        {
   416→            ProcessingResult.Success => ValidationResult.Valid,
   417→            ProcessingResult.ProcessingError => ValidationResult.Invalid,
   418→            _ => null
   419→        };

